using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using HimoHitoA2Proof;
using UnityEngine;

namespace HimoHito
{
    // Read-only diagnostic hooks; do not change body, input, or collision settings.
    public static class RetryStateTrace
    {
        // Isolated comparison switch only. Default manual launch uses the synchronized path.
        public static bool SynchronizeEnabled=>A2Fixture.Arg("-retrySync","fixed")!="baseline";
        public static RetryStateReview Owner;
        public static bool Enabled;
        public static void Record(string label){if(Enabled&&Owner)Owner.Record(label);}
        public static void Sweep(Vector2 from,Vector2 to,RaycastHit2D[] hits,RaycastHit2D chosen,float safe)
        {if(Enabled&&Owner)Owner.Sweep(from,to,hits,chosen,safe);}
    }
    [DefaultExecutionOrder(20000)]
    public sealed class RetryStateReview:MonoBehaviour
    {
        A2Fixture f;A2InputDriver input;Case active;Result result=new Result();bool film,filming;int frame;string movieFolder;RetryUpdatePulse pulse;
        [Serializable]public class State
        {
            public string label;public int frame;public float t,fixedTime,input,driverInput,remaining,coyote,jumpBuffer,airTime,previousVertical;
            public Vector2 position,transformPosition,previousPhysics,velocity,colliderMin,colliderMax;
            public Vector3 camera;public float ortho;
            public bool hasPrevious,hasPreviousVertical,attached,grounded,simulated,failure,moverEnabled;
            public int selected,bridges;public string hook;public bool hooksRestored;
        }
        [Serializable]public class Hit{public string collider;public float distance;public Vector2 point,normal;public bool solid;}
        [Serializable]public class SweepEvent{public State before;public Vector2 from,to;public float distance,safeDistance;public string chosenCollider;public List<Hit> hits=new List<Hit>();}
        [Serializable]public class Case
        {
            public string name,method;public bool passed,finished,attachedAccepted,bridgeCreated;public State before,immediate,settled;
            public List<State> states=new List<State>();public List<State> approach=new List<State>();public List<SweepEvent> sweeps=new List<SweepEvent>();
        }
        [Serializable]public class Result{public string method="Automatic existing input-field/API, NOT OS keys/Human.",mode,sync;public bool finished;public int errors;public List<Case> cases=new List<Case>();}
        float origin;
        public State Observe(string label)
        {
            var c=f.Body.GetComponent<Collider2D>();var m=f.Mover;var ty=typeof(PlayerMover);
            object Field(string name)=>ty.GetField(name,A2Fixture.Private).GetValue(m);
            return new State{label=label,frame=Time.frameCount,t=Time.time-origin,fixedTime=Time.fixedTime,position=f.Body.position,transformPosition=f.Body.transform.position,
                previousPhysics=(Vector2)Field("previousPhysicsPosition"),hasPrevious=(bool)Field("hasPreviousPhysicsPosition"),velocity=f.Body.linearVelocity,
                input=m.MovementInput,driverInput=input?input.Move:0,remaining=f.Resource.CurrentLength,selected=f.Rope.SelectedRopeLength,bridges=f.Builder.GeneratedPlatformCount,
                attached=f.Rope.IsAttached,hook=f.Rope.ActiveHookPoint?f.Rope.ActiveHookPoint.name:"",grounded=m.IsGrounded,simulated=f.Body.simulated,failure=f.Respawn.IsFailureVisible,moverEnabled=m.enabled,
                coyote=(float)Field("coyoteTimer"),jumpBuffer=(float)Field("jumpBufferTimer"),airTime=(float)Field("landingFluffAirTime"),previousVertical=(float)Field("previousVerticalSpeed"),hasPreviousVertical=(bool)Field("hasPreviousVerticalSpeed"),
                colliderMin=c.bounds.min,colliderMax=c.bounds.max,hooksRestored=Array.TrueForAll(f.BHooks,g=>g&&g.activeInHierarchy),camera=Camera.main.transform.position,ortho=Camera.main.orthographicSize};
        }
        public void Record(string label){if(active!=null)active.states.Add(Observe(label));}
        public void Sweep(Vector2 from,Vector2 to,RaycastHit2D[] hits,RaycastHit2D chosen,float safe)
        {
            var s=new SweepEvent{before=Observe("sweep.beforePositionWrite"),from=from,to=to,distance=Vector2.Distance(from,to),safeDistance=safe,chosenCollider=chosen.collider.name};
            foreach(var h in hits)s.hits.Add(new Hit{collider=h.collider?h.collider.name:"",distance=h.distance,point=h.point,normal=h.normal,solid=h.collider&&h.collider.GetComponent<SolidSwingSurface>()});active.sweeps.Add(s);
        }
        IEnumerator Start()
        {
            while(!(f=A2Fixture.Instance)||!f.Ready||!f.Body.GetComponent<PlayerMotionPresentation>())yield return null;
            while(Time.time<1)yield return null;
            input=f.gameObject.AddComponent<A2InputDriver>();RetryStateTrace.Owner=this;
            pulse=f.Body.gameObject.AddComponent<RetryUpdatePulse>();pulse.owner=this;
            result.mode=A2Fixture.Arg("-retryMode","original");result.sync=A2Fixture.Arg("-retrySync","fixed");
            f.Write("RetryConfig.json",new A2Fixture.Config(f));f.Write("RetryLayout.json",new A2Fixture.Layout(f));
            film=A2Fixture.Arg("-retryFilm","0")=="1";
            yield return OriginalFollow(false);
            if(result.mode=="matrix")
            {
                yield return OriginalFollow(true);
                foreach(string name in new[]{"NearWallAir","HighAir","FarExit","HeldRightAfterR","AfterBridge"})yield return Positioned(name);
                yield return NoRetrySwing(6,42);yield return NoRetrySwing(7,54);
            }
            result.finished=true;result.errors=f.Errors;f.Write("RetryResult.json",result);
            yield return new WaitForSeconds(.1f);A2Fixture.Quit(f.Errors==0?0:2);
        }
        IEnumerator OriginalFollow(bool updatePath)
        {
            input.enabled=true;
            input.Move=0;input.Jump=false;f.ResetTrial();yield return new WaitForSeconds(1.7f);
            active=new Case{name=updatePath?"L6_follow_driverDisabled_UpdateCoreR":"L6_ground_follow_release-1",method=updatePath?"Same natural approach; A2InputDriver disabled before R; invoke the unchanged normal R core method from Update, not fixture Retry wrapper. NOT OS R.":"Original WallCollisionReview Run sequence: same 1.7s reset wait, attached6, velocity-follow input5s, then input.Move=0 and f.Retry."};
            result.cases.Add(active);origin=Time.time;f.Rope.RestoreSelectedRopeLength(6);
            active.attachedAccepted=f.Rope.TryAttach(GameObject.Find(A2Fixture.SwingNames[0]).transform.position);input.Move=1;
            float started=Time.fixedTime;
            while(Time.fixedTime<started+5)
            {
                if(f.Rope.IsAttached)input.Move=Mathf.Abs(f.Body.linearVelocity.x)>.1f?Mathf.Sign(f.Body.linearVelocity.x):input.Move;
                else input.Move=1;
                if(Time.fixedTime>started+4.9f)RetryStateTrace.Enabled=true;
                active.approach.Add(Observe("approach"));
                if(film&&!filming&&Time.fixedTime>started+4.6f){movieFolder=Path.Combine(f.Output,"Frames");Directory.CreateDirectory(movieFolder);frame=0;filming=true;StartCoroutine(Frames());}
                yield return new WaitForFixedUpdate();
            }
            if(Application.isBatchMode)yield return null;else yield return new WaitForEndOfFrame();
            input.Move=0;
            if(updatePath){input.enabled=false;pulse.requested=true;while(pulse.requested)yield return null;}
            else PerformRetry(false);
            yield return new WaitForSeconds(1.6f);active.settled=Observe("settled1.6s");active.passed=ValidEntry();active.finished=true;filming=false;
            RetryStateTrace.Enabled=false;Debug.Log("RETRY_CASE "+active.name+" pass="+active.passed);
        }
        public void PerformRetry(bool fromUpdate)
        {
            active.before=Observe("beforeRetry");
            if(fromUpdate)typeof(MainStageRespawnOnFall).GetMethod("RestartFromCheckpoint",A2Fixture.Private).Invoke(f.Respawn,null);else f.Retry();
            active.immediate=Observe("immediateRetry");
        }
        IEnumerator Positioned(string name)
        {
            input.enabled=true;input.Move=0;input.Jump=false;f.ResetTrial();yield return new WaitForSeconds(1.7f);
            active=new Case{name=name,method="Diagnostic setup of position (not route success), then same normal R core method from Update. No post-R position/velocity writes by QA."};result.cases.Add(active);origin=Time.time;
            if(name=="AfterBridge")
            {
                f.Rope.RestoreSelectedRopeLength(11);bool a=f.Rope.TryAttach(GameObject.Find(A2Fixture.EndNames[0]).transform.position);
                active.bridgeCreated=a&&f.Builder.TryBuildCurrentPlatform();yield return new WaitForSeconds(.4f);
            }
            else
            {
                Vector2 p=name=="NearWallAir"?A2Fixture.Global(.45f,-1):name=="HighAir"?A2Fixture.Global(5,3):name=="FarExit"?A2Fixture.Global(29.5f,-.6f):A2Fixture.Global(-2,.6f);
                f.Body.position=p;f.Body.transform.position=p;f.Body.linearVelocity=Vector2.zero;Physics2D.SyncTransforms();
                // Diagnostic setup only: start this isolated state with matching history.
                // Otherwise the setup teleport itself could trigger the very bug under test.
                typeof(PlayerMover).GetField("previousPhysicsPosition",A2Fixture.Private).SetValue(f.Mover,p);
                typeof(PlayerMover).GetField("hasPreviousPhysicsPosition",A2Fixture.Private).SetValue(f.Mover,true);
                yield return new WaitForSeconds(.12f);
                f.Rope.RestoreSelectedRopeLength(7);
                active.attachedAccepted=f.Rope.TryAttach(GameObject.Find(A2Fixture.SwingNames[0]).transform.position);
            }
            RetryStateTrace.Enabled=true;
            if(name=="HeldRightAfterR")input.Move=1;else input.enabled=false;
            pulse.requested=true;while(pulse.requested)yield return null;
            yield return new WaitForSeconds(name=="HeldRightAfterR"?.06f:1.6f);
            active.settled=Observe("settled");
            active.passed=name=="HeldRightAfterR"?f.Body.position.x>f.Spawn.x&&f.Body.linearVelocity.x>0&&!f.Rope.IsAttached&&f.Resource.CurrentLength==24&&f.Builder.GeneratedPlatformCount==0:ValidEntry();
            active.finished=true;RetryStateTrace.Enabled=false;input.Move=0;
            Debug.Log("RETRY_CASE "+name+" pass="+active.passed);
        }
        IEnumerator Frames()
        {
            while(filming)
            {
                yield return new WaitForEndOfFrame();if(!filming)break;
                var image=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(Path.Combine(movieFolder,"Frame_"+frame.ToString("D4")+".jpg"),image.EncodeToJPG(78));Destroy(image);frame++;
            }
        }
        IEnumerator NoRetrySwing(int length,float angle)
        {
            input.enabled=true;input.Move=0;input.Jump=false;f.ResetTrial();yield return new WaitForSeconds(1.7f);
            active=new Case{name="NoRetry_SwingReleaseLanding_L"+length,method="Automatic initial setup R, then no R during swing/release/landing. Compare full approach trace between baseline/fixed."};result.cases.Add(active);origin=Time.time;
            f.Rope.RestoreSelectedRopeLength(length);active.attachedAccepted=f.Rope.TryAttach(GameObject.Find(A2Fixture.SwingNames[0]).transform.position);input.Move=1;
            float deadline=Time.time+7;bool released=false;
            while(Time.time<deadline&&!f.Respawn.IsFailureVisible)
            {
                active.approach.Add(Observe("noRetryStep"));var d=f.Body.position-f.Rope.AnchorPoint;
                if(!released&&Mathf.Atan2(d.x,-d.y)*Mathf.Rad2Deg>=angle&&f.Body.linearVelocity.x>0&&f.Body.linearVelocity.y>0){f.Rope.DetachAndRefund(true);released=true;}
                if(released&&f.OnBank(f.Middle))break;
                yield return new WaitForFixedUpdate();
            }
            input.Move=0;yield return new WaitForSeconds(.3f);active.settled=Observe("landedNoRetry");active.passed=released&&f.OnBank(f.Middle)&&f.Resource.CurrentLength==24&&!f.Rope.IsAttached;active.finished=true;
            Debug.Log("RETRY_CASE "+active.name+" pass="+active.passed);
        }
        bool ValidEntry()=>f.Body.simulated&&f.Mover.IsGrounded&&!f.Rope.IsAttached&&!f.Respawn.IsFailureVisible&&Vector2.Distance(f.Body.position,f.Spawn)<.18f&&f.Resource.CurrentLength==24&&f.Rope.SelectedRopeLength==6&&f.Builder.GeneratedPlatformCount==0&&Array.TrueForAll(f.BHooks,g=>g&&g.activeInHierarchy);
        void LateUpdate(){if(RetryStateTrace.Enabled)Record("late.afterPhysics");}
    }
    [DefaultExecutionOrder(-201)]public sealed class RetryUpdatePulse:MonoBehaviour
    {
        public RetryStateReview owner;public bool requested;
        void Update(){if(requested){requested=false;owner.PerformRetry(true);}}
    }
}
